// Function that processes order events in serverless environment
public class OrderHandler implements Function<Order, OrderConfirmation> {

    @Override
    public OrderConfirmation apply(Order order) {
        // No @SpringBootApplication, no ApplicationContext overhead
        var confirmation = new OrderConfirmation(
            order.id(),
            "CONFIRMED",
            Instant.now()
        );

        // Business logic runs directly
        if (order.amount() > 1000) {
            confirmation = confirmation.withStatus("PENDING_REVIEW");
        }

        return confirmation;
    }
}

record Order(String id, double amount, String customerId) {}
record OrderConfirmation(String orderId, String status, Instant timestamp) {
    OrderConfirmation withStatus(String newStatus) {
        return new OrderConfirmation(orderId, newStatus, timestamp);
    }
}

// application.yml with environment variable substitution
// Factor III: Store config in environment, not code
spring:
  datasource:
    url: ${DATABASE_URL}  // Injected from environment
    username: ${DB_USERNAME}
    password: ${DB_PASSWORD}
  profiles:
    active: ${SPRING_PROFILE:dev}  // Default to dev if not set

@RestController
public class OrderController {

    private final OrderRepository repository;

    // Factor IV: Treat backing services as attached resources
    // Repository abstraction lets us swap implementations
    public OrderController(OrderRepository repository) {
        this.repository = repository;
    }

    @GetMapping("/orders/{id}")
    public Order getOrder(@PathVariable Long id) {
        // Factor VI: Stateless processes—no session data in memory
        // Each request is independent, can be handled by any instance
        return repository.findById(id)
            .orElseThrow(() -> new OrderNotFoundException(id));
    }
}

// Configuration that adapts to cost constraints
@Configuration
public class CostAwareConfig {

    @Value("${app.environment}")
    private String environment;

    @Bean
    public DataSource dataSource() {
        var config = new HikariConfig();
        config.setJdbcUrl(System.getenv("DATABASE_URL"));

        // Dev: smaller connection pool to reduce RDS costs
        // Prod: larger pool for performance
        if ("dev".equals(environment)) {
            config.setMaximumPoolSize(5);  // Minimize RDS connections
        } else {
            config.setMaximumPoolSize(20);
        }

        return new HikariDataSource(config);
    }

    @Bean
    public CacheManager cacheManager() {
        // Dev: use in-memory cache (free)
        // Prod: use Redis (costs money but needed for multi-instance)
        if ("dev".equals(environment)) {
            return new ConcurrentMapCacheManager("orders");
        }
        return new RedisCacheManager(redisConnectionFactory());
    }
}
